function columns(PDO $db, string $table): array { return array_column($db->query("PRAGMA table_info($table)")->fetchAll(PDO::FETCH_ASSOC), 'name'); }
function addColumn(PDO $db, string $table, string $column, string $definition): void { if (!in_array($column, columns($db, $table), true)) $db->exec("ALTER TABLE $table ADD COLUMN $column $definition"); }
