function json(mixed $body, int $status = 200): never { http_response_code($status); header('Content-Type: application/json'); echo json_encode($body, JSON_UNESCAPED_SLASHES); exit; }
function input(): array { $data = json_decode(file_get_contents('php://input'), true); return is_array($data) ? $data : []; }
function one(PDO $db, string $sql, array $params = []): ?array { $statement = $db->prepare($sql); $statement->execute($params); $row = $statement->fetch(PDO::FETCH_ASSOC); return $row ?: null; }
function all(PDO $db, string $sql, array $params = []): array { $statement = $db->prepare($sql); $statement->execute($params); return $statement->fetchAll(PDO::FETCH_ASSOC); }
function execute(PDO $db, string $sql, array $params = []): PDOStatement { $statement = $db->prepare($sql); $statement->execute($params); return $statement; }
function value(array $data, string $key): mixed { return $data[$key] ?? null; }
function cardExists(PDO $db, string $id): bool { return one($db, 'SELECT id FROM cards WHERE id = ?', [$id]) !== null; }
function cardSlug(string $companyName): string { $slug = iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $companyName) ?: $companyName; $slug = strtolower(trim((string)preg_replace('/[^a-zA-Z0-9]+/', '-', $slug), '-')); $slug = $slug === '' ? 'card' : $slug; return ctype_digit($slug) ? "company-$slug" : $slug; }
function cardPath(PDO $db, array $card): string { $cards = all($db, 'SELECT id, company_name FROM cards'); $slugs = array_map(fn($item) => cardSlug((string)$item['company_name']), $cards); $slug = cardSlug((string)$card['company_name']); $candidate = count(array_keys($slugs, $slug, true)) > 1 ? "$slug-{$card['id']}" : $slug; $candidates = array_map(fn($item, $itemSlug) => count(array_keys($slugs, $itemSlug, true)) > 1 ? "$itemSlug-{$item['id']}" : $itemSlug, $cards, $slugs); return '/cards/' . (count(array_keys($candidates, $candidate, true)) > 1 ? "$candidate-{$card['id']}" : $candidate); }
function publicCard(PDO $db, string $reference): ?array { if (ctype_digit($reference)) return one($db, "SELECT cards.* FROM cards WHERE cards.id = ? AND cards.card_status = 'Active'", [$reference]); foreach (all($db, "SELECT cards.* FROM cards WHERE cards.card_status = 'Active'") as $card) if (cardPath($db, $card) === '/cards/' . $reference) return $card; return null; }
function saveUploads(string $prefix): array { $saved = []; foreach ($_FILES as $field => $file) { $names = is_array($file['name']) ? $file['name'] : [$file['name']]; $temps = is_array($file['tmp_name']) ? $file['tmp_name'] : [$file['tmp_name']]; $sizes = is_array($file['size']) ? $file['size'] : [$file['size']]; foreach ($names as $i => $name) { if (!$name || ($sizes[$i] ?? 0) > 250 * 1024 || !is_uploaded_file($temps[$i])) continue; $clean = preg_replace('/[^a-zA-Z0-9._-]/', '-', basename($name)); $filename = round(microtime(true) * 1000) . '-' . $prefix . '-' . $clean; if (move_uploaded_file($temps[$i], UPLOAD_DIRECTORY . '/' . $filename)) $saved[] = [$field, '/uploads/' . $filename]; } } return $saved; }
function saveQrUploads(): array { $columns = ['paytmQrImage' => 'paytm_qr_url', 'googlePayQrImage' => 'google_pay_qr_url', 'phonepeQrImage' => 'phonepe_qr_url']; $saved = []; foreach ($columns as $field => $column) { $file = $_FILES[$field] ?? null; if (!$file || $file['error'] === UPLOAD_ERR_NO_FILE) continue; if ($file['error'] !== UPLOAD_ERR_OK) json(['error' => 'Unable to upload the QR image. Please try again.'], 400); if ($file['size'] > 250 * 1024) json(['error' => 'Each QR image must be 250 KB or smaller.'], 400); $image = is_uploaded_file($file['tmp_name']) ? @getimagesize($file['tmp_name']) : false; if (!$image) json(['error' => 'Upload a valid image file for each QR code.'], 400); $extension = image_type_to_extension($image[2], false); if (!in_array($extension, ['gif', 'jpeg', 'png', 'webp'], true)) json(['error' => 'QR images must be GIF, JPEG, PNG, or WebP files.'], 400); $filename = round(microtime(true) * 1000) . '-qr-' . $field . '.' . $extension; if (!move_uploaded_file($file['tmp_name'], UPLOAD_DIRECTORY . '/' . $filename)) json(['error' => 'Unable to save the QR image. Please try again.'], 500); $saved[$column] = '/uploads/' . $filename; } return $saved; }

