ey) => value($data, $key) ?: null, $keys); $sql = 'UPDATE cards SET ' . implode(', ', array_map(fn($column) => "$column = ?", $columns)) . ' WHERE id = ?'; execute($db, $sql, [...$values, $id]); if ($route === 'details') { execute($db, 'UPDATE customers SET phone = ? WHERE id = (SELECT customer_id FROM cards WHERE id = ?)', [value($data, 'phone'), $id]); json(one($db, 'SELECT * FROM cards WHERE id = ?', [$id])); } json(['success' => true]); }
